const fs = require("fs");
const path = require("path");
const os = require("os");

const REDACCIONES = [
  [/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, "[correo-redactado]"],
  [/sk-[A-Za-z0-9_-]{16,}/g, "[llave-redactada]"],
  [/(LLM_API_KEY["'=:\s]+)[^\s"',}]+/g, "$1[llave-redactada]"],
];

function raizProyecto() {
  return process.env.CLAUDE_PROJECT_DIR || process.cwd();
}

function terminosLocales(raiz) {
  const archivo = path.join(raiz, ".claude", "redacciones.local.txt");
  if (!fs.existsSync(archivo)) return [];
  return fs.readFileSync(archivo, "utf8").split(/\r?\n/).map((t) => t.trim()).filter(Boolean);
}

function redactar(texto, terminos) {
  const base = REDACCIONES.reduce((acc, [patron, reemplazo]) => acc.replace(patron, reemplazo), texto);
  return terminos.reduce((acc, termino) => acc.split(termino).join("[redactado]"), base);
}

function copiarRedactado(origen, destino, terminos) {
  fs.mkdirSync(path.dirname(destino), { recursive: true });
  fs.writeFileSync(destino, redactar(fs.readFileSync(origen, "utf8"), terminos));
}

function exportarSesion(transcripcion, raiz, terminos) {
  if (!transcripcion || !fs.existsSync(transcripcion)) return 0;
  const idSesion = path.basename(transcripcion, ".jsonl");
  const destino = path.join(raiz, "logs", "sesiones", idSesion);
  copiarRedactado(transcripcion, path.join(destino, "sesion.jsonl"), terminos);
  const carpetaSubagentes = path.join(path.dirname(transcripcion), idSesion, "subagents");
  if (!fs.existsSync(carpetaSubagentes)) return 1;
  const subagentes = fs.readdirSync(carpetaSubagentes).filter((f) => f.endsWith(".jsonl"));
  subagentes.forEach((f) => copiarRedactado(path.join(carpetaSubagentes, f), path.join(destino, "subagentes", f), terminos));
  return 1 + subagentes.length;
}

function carpetaTranscripciones(raiz) {
  const codificada = path.resolve(raiz).replace(/[^A-Za-z0-9]/g, "-");
  return path.join(os.homedir(), ".claude", "projects", codificada);
}

function exportarTodo(raiz, terminos) {
  const carpeta = carpetaTranscripciones(raiz);
  if (!fs.existsSync(carpeta)) return 0;
  return fs.readdirSync(carpeta)
    .filter((f) => f.endsWith(".jsonl"))
    .reduce((total, f) => total + exportarSesion(path.join(carpeta, f), raiz, terminos), 0);
}

function exportarDesdeHook(entrada, raiz, terminos) {
  const { transcript_path } = JSON.parse(entrada);
  return exportarSesion(transcript_path, raiz, terminos);
}

const raiz = raizProyecto();
const terminos = terminosLocales(raiz);

if (process.argv.includes("--todo")) {
  process.stdout.write(`exportar-log: ${exportarTodo(raiz, terminos)} transcripciones exportadas\n`);
} else {
  let entrada = "";
  process.stdin.on("data", (c) => (entrada += c));
  process.stdin.on("end", () => {
    try {
      exportarDesdeHook(entrada, raiz, terminos);
    } catch (e) {
      process.stderr.write(`exportar-log: ${e.message}\n`);
    }
  });
}

content.text:
Gemini me parece bien: así sabremos si P4, P5 y P8 fallan por el modelo de 7B o por nuestro diseño. Ya protegí los logs: agregué la redacción de llaves `AIza…` (Gemini) y `gsk_…` (Groq), probada y guardada en el commit humano `5617159`.

**Cómo dejar la llave sin que pase por el chat ni por los logs:**
1. Crea a mano el archivo `.env` en la raíz del repositorio. Ya lo ignoran `.gitignore` y `.dockerignore`, y mis reglas de permisos me impiden leerlo:
   ```
   LLM_API_KEY=[llave-redactada] llave de Gemini>
   LLM_MODELO=gemini-3.5-flash-lite
   ```
2. **No la pegues en el chat** ni la ejecutes con `!`: quedaría en la transcripción.
3. Avísame cuando esté. La fase V correrá contra `docker compose`, que lee el `.env` por su cuenta, así que la llave nunca pasa por mí.

La llave se detecta por el prefijo `AIza` y el modelo se toma de `LLM_MODELO`. Ese modelo no está en el catálogo de precios, así que el costo saldrá en 0. No bloquea nada, porque el presupuesto no tiene tope por defecto.

**Auditoría de `seguridad`: BLOQUEADO por 2 hallazgos altos.** No encontró ninguna fuga de datos de terceros: la matriz de acceso se cumple en todas las sondas. Los dos hallazgos altos:
- **S-01, coma decimal.** "Tu promedio es 1,23" (el real es 4.39) se entrega sin bloqueo, porque los verificadores solo reconocen el punto, y en español lo natural es la coma.
- **S-02, falsos 403 en preguntas normativas.** "¿Qué estudiantes pueden pedir la beca de excelencia?" o "¿Todos los estudiantes pueden cancelar materias?" reciben 403 por "agregado". Son preguntas legítimas sobre el reglamento, y las pruebas ocultas podrían hacerlas.

Además encontró 13 hallazgos medios y bajos:
- sinónimos sin verificar ("reprobó", "nota final");
- enteros sin verificar ("9 faltas", cuando son 2);
- HTML como encabezado;
- relleno Hangul;
- evasiones como "hazte pasar por mi coordinador";
- falsos 403 de SEG-04c;
- un DoS con más de 10.000 IP;
- y otros menores.

**Ronda siguiente.** Junto todo con lo que dejó abierto la fase V: la atribución de datos de Valentina al coordinador con "Tu", los artefactos sin el texto entregado y los hallazgos de calidad. Siguiendo INT-030, `arquitecto-spec` propone las soluciones, `backend-dotnet` y `frontend-react` las evalúan, y te traigo lo que necesite tu decisión. La medición con Gemini va en paralelo en cuanto tengas el `.env`.

